### acme/aidenhq fix/outside-close-reason (3f1e2d4c5b6a)
diff --git a/services/runner/src/tiers.mjs b/services/runner/src/tiers.mjs
index 1a2b3c4..5d6e7f8 100644
--- a/services/runner/src/tiers.mjs
+++ b/services/runner/src/tiers.mjs
@@ -152,5 +152,5 @@ function closeParts(s) {
       return T(0, "product-dependabot-close", "closing a Dependabot PR of the product repo is reversible (reopen) and changes no code");
     }
-    if (!same(orgOf(p.repo), s.agentsOrg)) return REJECT("outside-close", `${p.repo} is outside the agents org`);
+    if (!same(orgOf(p.repo), s.agentsOrg)) return REJECT("outside-close", `${p.repo} is outside the agents org, so the runner can't close it`);
     if (same(p.repo, s.instanceRepo)) return REJECT("core-repo-close", `${p.repo} is the instance repo: its PRs are the owner's`);
     return T(0, "agents-org-close", `closing a PR of ${p.repo} is reversible and changes no code`);
diff --git a/services/runner/test/tiers.test.mjs b/services/runner/test/tiers.test.mjs
index 9a8b7c6..0f1e2d3 100644
--- a/services/runner/test/tiers.test.mjs
+++ b/services/runner/test/tiers.test.mjs
@@ -60,3 +60,8 @@ test("close", () => {
   assert.equal(close({ repo: "other/x" }).reject, true);
 });
+
+test("an outside close says why", () => {
+  assert.match(close({ repo: "other/x" }).reason, /can't close it/);
+  assert.equal(close({ repo: "other/x" }).reject, true);
+});
